<!-- @FIGURE_UI_BEGIN -->
<label><input id="targetViewInput" type="checkbox" onchange="toggle_targetView(this.checked)"> Overlay comparison</label><span id="demoNarration" style="display:block;margin:0;font-size:10px;max-width:180px;line-height:1.25"></span><span style="display:flex;gap:4px;align-items:center;flex-wrap:wrap"><button onclick="prevStep()">◀</button><span id="stepLabel"></span><button onclick="nextStep()">▶</button></span><span style="display:block;font-size:10px;line-height:1.25;color:#444">Click an archer to classify the pattern. After selecting, drag the orange shot to test a new measurement.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 1200, H = 470;
draw.viewbox(0, 0, W, H);

var blue = '#8d97cf';
var border = '#555555';
var labelColor = '#222222';
var highlightColor = '#f28c28';

var panelDefs = [
  { key: 'W', name: 'Archer W', x: 6, y: 8, w: 289, h: 400 },
  { key: 'X', name: 'Archer X', x: 305, y: 8, w: 289, h: 400 },
  { key: 'Y', name: 'Archer Y', x: 604, y: 8, w: 289, h: 400 },
  { key: 'Z', name: 'Archer Z', x: 903, y: 8, w: 289, h: 400 }
];

var baseShots = {
  W: [
    [-36, -42], [25, -37], [-16, 30], [27, 23]
  ],
  X: [
    [43, 120], [62, 109], [67, 125], [70, 145]
  ],
  Y: [
    [-76, -112], [88, -196], [-116, 62], [75, 137]
  ],
  Z: [
    [-62, -52], [42, 13], [57, -168], [39, 145]
  ]
};

var overlayColors = {
  W: '#111111',
  X: '#d95f02',
  Y: '#1b9e77',
  Z: '#7570b3'
};

var extraShots = {};
var selectedArcher = null;
var overlayMode = false;
var currentStep = 0;
var dragState = null;
var candidateRel = null;
var activeCalloutGroup = null;
var activeDragDot = null;

var demoSteps = [
  {
    title: 'Read one target at a time',
    narration: "Click Archer W, X, Y, or Z to highlight the panel and see its precision and accuracy classification. Notice that the callout uses two different visual cues: clustering for precision and closeness to the center for accuracy.",
    state: { targetView: 'Separate panels' }
  },
  {
    title: 'Compare W and X',
    narration: "Archer W and Archer X both have tightly grouped shots, so both are precise. Only W is accurate because its cluster is near the bullseye, while X's cluster is reproducible but far from the true value.",
    state: { targetView: 'Separate panels' }
  },
  {
    title: 'Compare all patterns directly',
    narration: "Switch to the overlay view to place all four shot groups on one target. This makes the contrast between tight clusters, scattered shots, centered groups, and off-center groups visible at once.",
    state: { targetView: 'Overlay comparison' }
  },
  {
    title: 'Test a new measurement',
    narration: "Drag a new shot onto any archer's target and watch the rating update. A shot near the existing cluster may preserve precision, while a faraway shot usually lowers precision even if it lands closer to the center.",
    state: { targetView: 'Separate panels' }
  }
];

function panelCenter(p) {
  return { x: p.x + p.w / 2, y: 229 };
}

function shotsFor(key, tempRel) {
  var arr = baseShots[key].slice();
  if (extraShots[key]) arr.push(extraShots[key]);
  if (tempRel && selectedArcher === key) arr.push(tempRel);
  return arr;
}

function ratingFor(key, tempRel) {
  var arr = shotsFor(key, tempRel);
  var sx = 0, sy = 0;
  for (var i = 0; i < arr.length; i++) {
    sx += arr[i][0];
    sy += arr[i][1];
  }
  var mx = sx / arr.length, my = sy / arr.length;
  var ss = 0;
  for (var j = 0; j < arr.length; j++) {
    var dx = arr[j][0] - mx, dy = arr[j][1] - my;
    ss += dx * dx + dy * dy;
  }
  var spread = Math.sqrt(ss / arr.length);
  var centerDistance = Math.sqrt(mx * mx + my * my);
  var precise = spread <= 45;
  var accurate = centerDistance <= 26;
  var explanation;
  if (precise && accurate) {
    explanation = 'Tight cluster near bullseye: high precision and high accuracy.';
  } else if (precise && !accurate) {
    explanation = 'Tight cluster far from bullseye: high precision but low accuracy.';
  } else if (!precise && accurate) {
    explanation = 'Scattered shots balance near the bullseye: low precision but high accuracy on average.';
  } else {
    explanation = 'Scattered shots with an off-center group: low precision and low accuracy.';
  }
  return {
    meanX: mx,
    meanY: my,
    spread: spread,
    centerDistance: centerDistance,
    precision: precise ? 'High' : 'Low',
    accuracy: accurate ? 'High' : 'Low',
    explanation: explanation
  };
}

function drawTarget(g, cx, cy, scale) {
  scale = scale || 1;
  var outer = g.circle(228 * scale).center(cx, cy).fill(blue).stroke('none');
  g.circle(154 * scale).center(cx, cy).fill('#ffffff').stroke('none');
  g.circle(88 * scale).center(cx, cy).fill(blue).stroke('none');
  outer.on('mousemove', function (e) { showTooltip('The bullseye represents the true value.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('True value', 'Accuracy is judged by how close the group center is to the bullseye, not by how tightly the shots cluster.');
    })
    .css('cursor', 'pointer');
}

function drawShot(g, x, y, color, tooltip, strokeColor, r) {
  r = r || 7.2;
  var dot = g.circle(2 * r).center(x, y).fill(color).stroke(strokeColor ? { color: strokeColor, width: 2 } : 'none');
  g.line(x - r - 2, y, x + r + 2, y).stroke({ color: color, width: 1.1, linecap: 'round' });
  g.line(x, y - r - 2, x, y + r + 2).stroke({ color: color, width: 1.1, linecap: 'round' });
  dot.on('mousemove', function (e) { showTooltip(tooltip || 'A repeated measurement.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function (e) {
      e.stopPropagation();
      showPopup('Shot dot', 'Each dot is one repeated measurement. Precision depends on how close these dots are to one another.');
    })
    .css('cursor', 'pointer');
  return dot;
}

function drawSeparate() {
  for (var i = 0; i < panelDefs.length; i++) {
    drawPanel(panelDefs[i]);
  }
}

function drawPanel(p) {
  var g = draw.group();
  g.rect(p.w, p.h).move(p.x, p.y).fill('#ffffff').stroke({ color: border, width: 3 });

  var c = panelCenter(p);
  drawTarget(g, c.x, c.y, 1);

  var allShots = shotsFor(p.key);
  for (var i = 0; i < allShots.length; i++) {
    var isExtra = extraShots[p.key] && i === allShots.length - 1;
    drawShot(
      g,
      c.x + allShots[i][0],
      c.y + allShots[i][1],
      isExtra ? '#ff9f1a' : '#000000',
      isExtra ? 'Added measurement: drag it to change the group.' : p.name + ' shot',
      isExtra ? '#ffffff' : null,
      isExtra ? 8 : 7
    );
  }

  draw.text(p.name)
    .font({ family: 'Arial, Helvetica, sans-serif', size: 27, anchor: 'middle' })
    .fill(labelColor)
    .center(p.x + p.w / 2, 446);

  var clickLayer = g.rect(p.w, p.h).move(p.x, p.y).fill({ color: '#ffffff', opacity: 0 }).stroke('none');
  clickLayer.attr({ 'pointer-events': 'all' });
  clickLayer.on('click', function () {
    selectedArcher = p.key;
    candidateRel = null;
    render();
  }).on('mousemove', function (e) {
    var r = ratingFor(p.key);
    showTooltip(p.name + ': precision ' + r.precision.toLowerCase() + ', accuracy ' + r.accuracy.toLowerCase(), e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).css('cursor', 'pointer');

  if (selectedArcher === p.key) {
    draw.rect(p.w - 8, p.h - 8).move(p.x + 4, p.y + 4)
      .fill('none').stroke({ color: highlightColor, width: 4 });
    drawCallout(p.key, p.x + 13, p.y + 13, candidateRel);
    drawDraggableShot(p);
  }
}

function drawCallout(key, x, y, tempRel) {
  if (activeCalloutGroup) activeCalloutGroup.remove();
  var info = ratingFor(key, tempRel);
  var p = panelDefs.filter(function (d) { return d.key === key; })[0];
  var name = p ? p.name : ('Archer ' + key);

  activeCalloutGroup = draw.group();
  activeCalloutGroup.rect(184, 88).move(x, y).radius(7)
    .fill({ color: '#ffffff', opacity: 0.92 })
    .stroke({ color: highlightColor, width: 1.6 });

  activeCalloutGroup.text(name)
    .font({ family: 'Arial, Helvetica, sans-serif', size: 17, weight: 'bold' })
    .fill('#222').move(x + 10, y + 7);

  activeCalloutGroup.text('Precision: ' + info.precision)
    .font({ family: 'Arial, Helvetica, sans-serif', size: 13 })
    .fill(info.precision === 'High' ? '#126d32' : '#9b2226')
    .move(x + 10, y + 32);

  activeCalloutGroup.text('Accuracy: ' + info.accuracy)
    .font({ family: 'Arial, Helvetica, sans-serif', size: 13 })
    .fill(info.accuracy === 'High' ? '#126d32' : '#9b2226')
    .move(x + 10, y + 50);

  activeCalloutGroup.text('spread ' + Math.round(info.spread) + ', offset ' + Math.round(info.centerDistance))
    .font({ family: 'Arial, Helvetica, sans-serif', size: 11 })
    .fill('#555')
    .move(x + 10, y + 68);

  activeCalloutGroup.on('mousemove', function (e) { showTooltip(info.explanation, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup(name, info.explanation + ' Accuracy uses the group center relative to the bullseye; precision uses the spread around the group center.');
    })
    .css('cursor', 'pointer');
}

function drawDraggableShot(p) {
  var c = panelCenter(p);
  var rel = extraShots[p.key] || [0, 0];
  activeDragDot = draw.group();
  activeDragDot.circle(20).center(c.x + rel[0], c.y + rel[1])
    .fill('#ff9f1a').stroke({ color: '#ffffff', width: 3 });
  activeDragDot.circle(30).center(c.x + rel[0], c.y + rel[1])
    .fill({ color: '#ff9f1a', opacity: 0.16 }).stroke({ color: '#ff9f1a', width: 1.3, dasharray: '4,3' });

  activeDragDot.on('pointerdown', function (e) {
    e.preventDefault();
    e.stopPropagation();
    selectedArcher = p.key;
    dragState = { key: p.key, panel: p };
    candidateRel = rel.slice();
  }).on('mousemove', function (e) {
    showTooltip('Drag to place a new shot; ratings update from the new group.', e);
  }).on('mouseleave', function () {
    if (!dragState) hideTooltip();
  }).css('cursor', 'grab');
}

function drawOverlay() {
  var g = draw.group();
  var cx = 430, cy = 235, scale = 1.18;
  drawTarget(g, cx, cy, scale);

  var order = ['W', 'X', 'Y', 'Z'];
  for (var i = 0; i < order.length; i++) {
    var key = order[i];
    var arr = shotsFor(key);
    for (var j = 0; j < arr.length; j++) {
      var col = overlayColors[key];
      drawShot(g, cx + arr[j][0] * scale, cy + arr[j][1] * scale, col, 'Archer ' + key + ' shot on shared target', '#ffffff', 7.5);
    }
    var r = ratingFor(key);
    var mx = cx + r.meanX * scale, my = cy + r.meanY * scale;
    g.circle(11).center(mx, my).fill('#ffffff').stroke({ color: overlayColors[key], width: 3 });
    g.text(key).font({ family: 'Arial, Helvetica, sans-serif', size: 12, weight: 'bold', anchor: 'middle' })
      .fill(overlayColors[key]).center(mx, my - 14);
  }

  drawLegendAndOverlayRatings(order);

  if (selectedArcher) {
    draw.rect(244, 102).move(855, 282).radius(7)
      .fill({ color: '#ffffff', opacity: 0.92 })
      .stroke({ color: highlightColor, width: 1.6 });
    drawCallout(selectedArcher, 865, 292, null);
  }

  var targetHotspot = g.circle(270).center(cx, cy).fill({ color: '#ffffff', opacity: 0 }).stroke('none');
  targetHotspot.attr({ 'pointer-events': 'all' });
  targetHotspot.on('mousemove', function (e) {
    showTooltip('All archers are plotted on one common bullseye, so cluster spread and center offset can be compared directly.', e);
  }).on('mouseleave', function () { hideTooltip(); });
  targetHotspot.back();
}

function drawLegendAndOverlayRatings(order) {
  var lg = draw.group();
  var x = 745, y = 72;
  lg.rect(340, 176).move(x, y).radius(8)
    .fill({ color: '#ffffff', opacity: 0.94 })
    .stroke({ color: '#c7c7c7', width: 1.5 });

  lg.text('Overlay comparison')
    .font({ family: 'Arial, Helvetica, sans-serif', size: 22, weight: 'bold' })
    .fill('#222')
    .move(x + 16, y + 13);

  lg.text('Same bullseye; different shot patterns')
    .font({ family: 'Arial, Helvetica, sans-serif', size: 13 })
    .fill('#555')
    .move(x + 16, y + 43);

  for (var i = 0; i < order.length; i++) {
    var key = order[i];
    var yy = y + 75 + i * 23;
    var r = ratingFor(key);
    lg.circle(13).center(x + 25, yy + 7).fill(overlayColors[key]).stroke({ color: '#ffffff', width: 2 });
    lg.text('Archer ' + key)
      .font({ family: 'Arial, Helvetica, sans-serif', size: 14, weight: 'bold' })
      .fill('#222').move(x + 43, yy - 1);
    lg.text('P: ' + r.precision + '   A: ' + r.accuracy)
      .font({ family: 'Arial, Helvetica, sans-serif', size: 13 })
      .fill('#333').move(x + 145, yy);
  }

  lg.on('mousemove', function (e) {
    showTooltip('P is precision: cluster tightness. A is accuracy: group-center closeness to the bullseye.', e);
  }).on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Overlay legend', 'The colored markers let you compare all archers on one shared target. A tight off-center cluster is precise but not accurate, showing that repeatability and correctness are independent.');
    }).css('cursor', 'pointer');
}

function render() {
  hideTooltip();
  draw.clear();
  activeCalloutGroup = null;
  activeDragDot = null;

  if (overlayMode) {
    drawOverlay();
  } else {
    drawSeparate();
  }
}

