<!-- @FIGURE_UI_BEGIN -->
<label style="display:flex;flex-direction:row;gap:5px;align-items:center"><input id="targetViewInput" type="checkbox" onchange="toggle_targetView(this.checked)"> Overlay</label><span style="display:flex;gap:4px;align-items:center;flex-wrap:wrap"><button onclick="prevStep()">◀</button><span id="stepLabel" style="font-size:10px;line-height:1.15">1/4</span><button onclick="nextStep()">▶</button><button onclick="trigger_guide()" id="guideBtn">Guide</button></span><span id="guideBody" style="display:none;font-size:10px;line-height:1.22;color:#333"><span id="demoNarration" style="display:block;margin:0 0 5px 0"></span><span style="display:block;color:#555">Click a panel to classify it. Select a panel, then drag the orange shot to test a new measurement.</span></span>
