// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 1200, H = 470;
draw.viewbox(0, 0, W, H);
draw.node.setAttribute('preserveAspectRatio', 'xMidYMin meet');

var blue = '#8d97cf';
var border = '#555555';
var labelColor = '#222222';
var highlightColor = '#f28c28';

var panelDefs = [
  { key: 'W', name: 'Archer W', x: 6, y: 8, w: 289, h: 400 },
  { key: 'X', name: 'Archer X', x: 305, y: 8, w: 289, h: 400 },
  { key: 'Y', name: 'Archer Y', x: 604, y: 8, w: 289, h: 400 },
  { key: 'Z', name: 'Archer Z', x: 903, y: 8, w: 289, h: 400 }
];

var baseShots = {
  W: [
    [-36, -42], [25, -37], [-16, 30], [27, 23]
  ],
  X: [
    [43, 120], [62, 109], [67, 125], [70, 145]
  ],
  Y: [
    [-76, -112], [88, -196], [-116, 62], [75, 137]
  ],
  Z: [
    [-62, -52], [42, 13], [90, -182], [70, 145]
  ]
};

var overlayColors = {
  W: '#111111',
  X: '#d95f02',
  Y: '#1b9e77',
  Z: '#7570b3'
};

var extraShots = {};
var selectedArcher = null;
var overlayMode = false;
var currentStep = 0;
var dragState = null;
var candidateRel = null;
var activeCalloutGroup = null;
var activeDragDot = null;
var guideOpen = false;

var demoSteps = [
  {
    title: 'Read one target',
    narration: "Click Archer W, X, Y, or Z to highlight the panel and see its precision and accuracy classification. Clustering tells you precision; closeness to the bullseye tells you accuracy.",
    state: { targetView: 'Separate panels' }
  },
  {
    title: 'Compare W and X',
    narration: "Archer W and Archer X both have tightly grouped shots, so both are precise. Only W is accurate because its cluster is near the bullseye; X is repeatable but wrong.",
    state: { targetView: 'Separate panels' }
  },
  {
    title: 'Overlay groups',
    narration: "Overlay mode places all four shot groups on one target. This makes cluster spread and group-center location easier to compare directly.",
    state: { targetView: 'Overlay comparison' }
  },
  {
    title: 'Add a shot',
    narration: "Drag the orange shot on the selected target. One new measurement can change precision by increasing spread and can change accuracy by shifting the group center.",
    state: { targetView: 'Separate panels' }
  }
];

function compactDock() {
  document.body.style.setProperty('--ui-size', '178px');
}
requestAnimationFrame(compactDock);
setTimeout(compactDock, 0);
setTimeout(compactDock, 150);
window.addEventListener('resize', function () { requestAnimationFrame(compactDock); });

function panelCenter(p) {
  return { x: p.x + p.w / 2, y: 229 };
}

function shotsFor(key, tempRel) {
  var arr = baseShots[key].slice();
  if (extraShots[key]) arr.push(extraShots[key]);
  if (tempRel && selectedArcher === key) arr.push(tempRel);
  return arr;
}

function ratingFor(key, tempRel) {
  var arr = shotsFor(key, tempRel);
  var sx = 0, sy = 0;
  for (var i = 0; i < arr.length; i++) {
    sx += arr[i][0];
    sy += arr[i][1];
  }
  var mx = sx / arr.length, my = sy / arr.length;
  var ss = 0;
  for (var j = 0; j < arr.length; j++) {
    var dx = arr[j][0] - mx, dy = arr[j][1] - my;
    ss += dx * dx + dy * dy;
  }
  var spread = Math.sqrt(ss / arr.length);
  var centerDistance = Math.sqrt(mx * mx + my * my);
  var precise = spread <= 45;
  var accurate = centerDistance <= 35;
  var explanation;
  if (precise && accurate) {
    explanation = 'Tight cluster near the bullseye: high precision and high accuracy.';
  } else if (precise && !accurate) {
    explanation = 'Tight cluster far from the bullseye: high precision but low accuracy.';
  } else if (!precise && accurate) {
    explanation = 'Scattered shots whose average is near the bullseye: low precision but high accuracy.';
  } else {
    explanation = 'Scattered shots with an off-center average: low precision and low accuracy.';
  }
  return {
    meanX: mx,
    meanY: my,
    spread: spread,
    centerDistance: centerDistance,
    precision: precise ? 'High' : 'Low',
    accuracy: accurate ? 'High' : 'Low',
    explanation: explanation
  };
}

function selectPanel(key) {
  selectedArcher = key;
  candidateRel = null;
  render();
}

function drawTarget(g, cx, cy, scale, key) {
  scale = scale || 1;
  var targetGroup = g.group();
  targetGroup.circle(228 * scale).center(cx, cy).fill(blue).stroke('none');
  targetGroup.circle(154 * scale).center(cx, cy).fill('#ffffff').stroke('none');
  targetGroup.circle(88 * scale).center(cx, cy).fill(blue).stroke('none');

  targetGroup.on('mousemove', function (e) {
    showTooltip('The bullseye is the true value; accuracy means closeness to it.', e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function (e) {
    if (e && e.stopPropagation) e.stopPropagation();
    if (key) selectedArcher = key;
    showPopup('True value', 'The bullseye represents the true value. Accuracy is judged by how close the group center is to the bullseye; precision is judged by how tightly the shots cluster.');
    if (key) render();
  }).css('cursor', 'pointer');
}

function starPoints(x, y, rOuter, rInner, points) {
  var s = [];
  var start = -Math.PI / 2;
  for (var i = 0; i < points * 2; i++) {
    var r = (i % 2 === 0) ? rOuter : rInner;
    var a = start + i * Math.PI / points;
    s.push((x + Math.cos(a) * r).toFixed(2) + ',' + (y + Math.sin(a) * r).toFixed(2));
  }
  return s.join(' ');
}

function drawShot(g, x, y, color, tooltip, strokeColor, r) {
  r = r || 5.5;
  var mark = g.group();
  mark.polygon(starPoints(x, y, r + 1.6, Math.max(2.2, r * 0.62), 8))
    .fill(color).stroke(strokeColor ? { color: strokeColor, width: 1.2, linejoin: 'round' } : 'none');
  mark.circle(r * 1.32).center(x, y).fill(color).stroke('none');
  mark.on('mousemove', function (e) {
    showTooltip(tooltip || 'One repeated measurement.', e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function (e) {
    if (e && e.stopPropagation) e.stopPropagation();
    showPopup('Shot mark', 'Each black mark is one repeated measurement. Precision depends on how close these marks are to one another.');
  }).css('cursor', 'pointer');
  return mark;
}

function drawSeparate() {
  for (var i = 0; i < panelDefs.length; i++) {
    drawPanel(panelDefs[i]);
  }
}

function drawPanel(p) {
  var g = draw.group();

  var bg = g.rect(p.w, p.h).move(p.x, p.y).fill('#ffffff').stroke('none');
  bg.on('click', function () {
    selectPanel(p.key);
  }).on('mousemove', function (e) {
    var r = ratingFor(p.key);
    showTooltip(p.name + ': precision ' + r.precision.toLowerCase() + ', accuracy ' + r.accuracy.toLowerCase(), e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).css('cursor', 'pointer');

  var c = panelCenter(p);
  drawTarget(g, c.x, c.y, 1, p.key);

  var allShots = shotsFor(p.key);
  for (var i = 0; i < allShots.length; i++) {
    var isExtra = extraShots[p.key] && i === allShots.length - 1;
    drawShot(
      g,
      c.x + allShots[i][0],
      c.y + allShots[i][1],
      isExtra ? '#ff9f1a' : '#000000',
      isExtra ? 'Added measurement: drag the orange shot to change the group.' : p.name + ' shot',
      isExtra ? '#ffffff' : null,
      isExtra ? 7 : 5.2
    );
  }

  g.rect(p.w, p.h).move(p.x, p.y).fill('none').stroke({ color: border, width: 3 });

  draw.text(p.name)
    .font({ family: 'Arial, Helvetica, sans-serif', size: 27, anchor: 'middle' })
    .fill(labelColor)
    .center(p.x + p.w / 2, 446);

  if (selectedArcher === p.key) {
    draw.rect(p.w - 8, p.h - 8).move(p.x + 4, p.y + 4)
      .fill('none').stroke({ color: highlightColor, width: 4 });
    drawCallout(p.key, p.x + 13, p.y + 13, candidateRel);
    drawDraggableShot(p);
  }
}

function drawCallout(key, x, y, tempRel) {
  if (activeCalloutGroup) activeCalloutGroup.remove();
  var info = ratingFor(key, tempRel);
  var p = panelDefs.filter(function (d) { return d.key === key; })[0];
  var name = p ? p.name : ('Archer ' + key);

  activeCalloutGroup = draw.group();
  activeCalloutGroup.rect(184, 88).move(x, y).radius(7)
    .fill({ color: '#ffffff', opacity: 0.93 })
    .stroke({ color: highlightColor, width: 1.6 });

  activeCalloutGroup.text(name)
    .font({ family: 'Arial, Helvetica, sans-serif', size: 17, weight: 'bold' })
    .fill('#222').move(x + 10, y + 7);

  activeCalloutGroup.text('Precision: ' + info.precision)
    .font({ family: 'Arial, Helvetica, sans-serif', size: 13 })
    .fill(info.precision === 'High' ? '#126d32' : '#9b2226')
    .move(x + 10, y + 32);

  activeCalloutGroup.text('Accuracy: ' + info.accuracy)
    .font({ family: 'Arial, Helvetica, sans-serif', size: 13 })
    .fill(info.accuracy === 'High' ? '#126d32' : '#9b2226')
    .move(x + 10, y + 50);

  activeCalloutGroup.text('spread ' + Math.round(info.spread) + ', offset ' + Math.round(info.centerDistance))
    .font({ family: 'Arial, Helvetica, sans-serif', size: 11 })
    .fill('#555')
    .move(x + 10, y + 68);

  activeCalloutGroup.on('mousemove', function (e) {
    showTooltip(info.explanation, e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function () {
    showPopup(name, info.explanation + ' Precision uses the spread around the group center; accuracy uses the group center relative to the bullseye.');
  }).css('cursor', 'pointer');
}

function drawDraggableShot(p) {
  var c = panelCenter(p);
  var rel = extraShots[p.key] || [0, 0];
  activeDragDot = draw.group();
  activeDragDot.circle(19).center(c.x + rel[0], c.y + rel[1])
    .fill('#ff9f1a').stroke({ color: '#ffffff', width: 3 });
  activeDragDot.circle(29).center(c.x + rel[0], c.y + rel[1])
    .fill({ color: '#ff9f1a', opacity: 0.14 }).stroke({ color: '#ff9f1a', width: 1.2, dasharray: '4,3' });

  activeDragDot.on('pointerdown', function (e) {
    e.preventDefault();
    e.stopPropagation();
    selectedArcher = p.key;
    dragState = { key: p.key, panel: p };
    candidateRel = rel.slice();
  }).on('mousemove', function (e) {
    showTooltip('Drag to place a new shot; ratings update as the group changes.', e);
  }).on('mouseleave', function () {
    if (!dragState) hideTooltip();
  }).css('cursor', 'grab');
}

function drawOverlay() {
  var g = draw.group();
  var cx = 424, cy = 235, scale = 1.18;
  drawTarget(g, cx, cy, scale, null);

  var order = ['W', 'X', 'Y', 'Z'];
  for (var i = 0; i < order.length; i++) {
    var key = order[i];
    var arr = shotsFor(key);
    for (var j = 0; j < arr.length; j++) {
      var col = overlayColors[key];
      drawShot(g, cx + arr[j][0] * scale, cy + arr[j][1] * scale, col, 'Archer ' + key + ' shot on the shared target', '#ffffff', 5.7);
    }
    var r = ratingFor(key);
    var mx = cx + r.meanX * scale, my = cy + r.meanY * scale;
    g.circle(11).center(mx, my).fill('#ffffff').stroke({ color: overlayColors[key], width: 3 });
    g.text(key).font({ family: 'Arial, Helvetica, sans-serif', size: 12, weight: 'bold', anchor: 'middle' })
      .fill(overlayColors[key])
      .attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3, 'stroke-linejoin': 'round' })
      .center(mx, my - 15);
  }

  drawLegendAndOverlayRatings(order);

  if (selectedArcher) {
    drawCallout(selectedArcher, 868, 292, null);
  }

  var targetHotspot = g.circle(270).center(cx, cy).fill({ color: '#ffffff', opacity: 0 }).stroke('none');
  targetHotspot.attr({ 'pointer-events': 'all' });
  targetHotspot.on('mousemove', function (e) {
    showTooltip('All archers are plotted on one common bullseye, so spread and offset can be compared directly.', e);
  }).on('mouseleave', function () {
    hideTooltip();
  });
  targetHotspot.back();
}

function drawLegendAndOverlayRatings(order) {
  var lg = draw.group();
  var x = 742, y = 72;
  lg.rect(344, 176).move(x, y).radius(8)
    .fill({ color: '#ffffff', opacity: 0.94 })
    .stroke({ color: '#c7c7c7', width: 1.5 });

  lg.text('Overlay comparison')
    .font({ family: 'Arial, Helvetica, sans-serif', size: 22, weight: 'bold' })
    .fill('#222')
    .move(x + 16, y + 13);

  lg.text('Same bullseye; different shot patterns')
    .font({ family: 'Arial, Helvetica, sans-serif', size: 13 })
    .fill('#555')
    .move(x + 16, y + 43);

  for (var i = 0; i < order.length; i++) {
    var key = order[i];
    var yy = y + 75 + i * 23;
    var r = ratingFor(key);
    lg.circle(13).center(x + 25, yy + 7).fill(overlayColors[key]).stroke({ color: '#ffffff', width: 2 });
    lg.text('Archer ' + key)
      .font({ family: 'Arial, Helvetica, sans-serif', size: 14, weight: 'bold' })
      .fill('#222').move(x + 43, yy - 1);
    lg.text('P: ' + r.precision + '   A: ' + r.accuracy)
      .font({ family: 'Arial, Helvetica, sans-serif', size: 13 })
      .fill('#333').move(x + 145, yy);
  }

  lg.on('mousemove', function (e) {
    showTooltip('P is precision: cluster tightness. A is accuracy: group-center closeness to the bullseye.', e);
  }).on('mouseleave', function () {
    hideTooltip();
  }).on('click', function () {
    showPopup('Overlay legend', 'The colored markers compare all four archers on one shared target. A tight off-center cluster is precise but not accurate, showing that repeatability and correctness are independent.');
  }).css('cursor', 'pointer');
}

function render() {
  hideTooltip();
  draw.clear();
  activeCalloutGroup = null;
  activeDragDot = null;

  if (overlayMode) {
    drawOverlay();
  } else {
    drawSeparate();
  }
}

function svgPoint(evt) {
  var pt = draw.node.createSVGPoint();
  pt.x = evt.clientX;
  pt.y = evt.clientY;
  return pt.matrixTransform(draw.node.getScreenCTM().inverse());
}

function clamp(v, a, b) {
  return Math.max(a, Math.min(b, v));
}

document.addEventListener('pointermove', function (e) {
  if (!dragState || !activeDragDot) return;
  var p = dragState.panel;
  var c = panelCenter(p);
  var pt = svgPoint(e);
  var x = clamp(pt.x, p.x + 12, p.x + p.w - 12);
  var y = clamp(pt.y, p.y + 12, p.y + p.h - 12);
  candidateRel = [x - c.x, y - c.y];

  activeDragDot.children()[0].center(x, y);
  activeDragDot.children()[1].center(x, y);

  if (selectedArcher) {
    drawCallout(selectedArcher, p.x + 13, p.y + 13, candidateRel);
  }
});

document.addEventListener('pointerup', function () {
  if (!dragState) return;
  if (candidateRel) {
    extraShots[dragState.key] = candidateRel.slice();
  }
  dragState = null;
  candidateRel = null;
  render();
});

function toggle_targetView(on) {
  overlayMode = !!on;
  candidateRel = null;
  render();
}

function setTargetViewByName(name) {
  var on = name === 'Overlay comparison';
  var input = document.getElementById('targetViewInput');
  if (input) input.checked = on;
  toggle_targetView(on);
}

function applyStep(i) {
  currentStep = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[currentStep];

  var narration = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narration) narration.textContent = step.narration;
  if (label) label.textContent = (currentStep + 1) + '/4: ' + step.title;

  if (step.state && step.state.targetView) {
    setTargetViewByName(step.state.targetView);
  }

  if (currentStep === 0) {
    selectedArcher = null;
  } else if (currentStep === 1) {
    selectedArcher = 'X';
  } else if (currentStep === 2) {
    selectedArcher = null;
  } else if (currentStep === 3) {
    selectedArcher = 'W';
  }
  render();
}

function prevStep() {
  applyStep(currentStep - 1);
}

function nextStep() {
  applyStep(currentStep + 1);
}

function trigger_guide() {
  guideOpen = !guideOpen;
  var body = document.getElementById('guideBody');
  var btn = document.getElementById('guideBtn');
  if (body) body.style.display = guideOpen ? 'block' : 'none';
  if (btn) btn.textContent = guideOpen ? 'Hide' : 'Guide';
  compactDock();
}

window.toggle_targetView = toggle_targetView;
window.prevStep = prevStep;
window.nextStep = nextStep;
window.trigger_guide = trigger_guide;

applyStep(0);
compactDock();
window.__markRendered();
// @FIGURE_CODE_END

